/* The 3D engine and GLB files are loaded only after an explicit user action. */
(()=>{
 window.addEventListener('load',()=>{const n=performance.getEntriesByType('navigation')[0];document.body.dataset.domReadyMs=String(Math.round(n?.domContentLoadedEventEnd||0));document.body.dataset.initial3dRequests=String(performance.getEntriesByType('resource').filter(r=>/vendor\/three|\.glb/.test(r.name)).length)});
 let scene=null,library=null,entries=[],active='gpu',references=false,loading=false;
 const names={board:'Motherboard',cpu:'Processor',ram:'Memory',gpu:'Graphics card',ssd:'SSD',hdd:'Hard drive',psu:'Power supply',case:'Case',fan:'Case fans'};
 const el=id=>document.getElementById(id),safe=escapeHTML;
 async function catalogModels(){if(!library){const r=await fetch('/model-library.json');if(!r.ok)throw Error('Model catalog unavailable');library=await r.json()}return library}
 function inspect(slot){active=slot;scene?.select(slot);document.querySelectorAll('.builder-row').forEach(r=>r.classList.toggle('is-linked',r.dataset.builderRow===slot));el('scene-components')?.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sceneSlot===slot)));const chosen=entries.filter(e=>e.slot===slot);if(!el('scene-inspector'))return;el('scene-inspector').innerHTML=chosen.length?chosen.map(e=>`<div class="scene-inspected"><strong>${safe(e.name)}</strong><p>${e.record?.model?'Check exact clearances and connectors before buying.':library?'No 3D view is available for this part yet.':'Open the preview to explore this part.'}${e.unplaced?' Placement unresolved: '+safe(e.unplaced):''}</p><a href="/learn/${encodeURIComponent(e.id)}.html">Product specifications</a>${e.record?.attribution?`<a href="/builder/model-credits/">3D creator credits</a>`:''}${e.record?.source?`<a href="${safe(e.record.source)}" target="_blank" rel="noopener noreferrer">Product source</a>`:''}</div>`).join(''):`<strong>${names[slot]}</strong><p>No part selected.</p>`;}
 function refreshList(){el('scene-components').innerHTML=Object.entries(names).map(([slot,name])=>`<button type="button" data-scene-slot="${slot}" aria-pressed="${active===slot}">${name}<span>${entries.filter(e=>e.slot===slot).length||'—'}</span></button>`).join('');el('scene-components').querySelectorAll('button').forEach(b=>b.onclick=()=>inspect(b.dataset.sceneSlot));inspect(active)}
 async function refreshScene(){if(!scene)return;const result=await scene.update(entries,{references});if(result.stale)return;const missing=entries.filter(e=>!e.record?.model).length;el('scene-status').textContent=`${result.rendered} ${result.rendered===1?'object':'objects'} shown${missing?' · '+missing+' selected parts have no model':''}${result.failed.length?' · Model loading failed: '+result.failed.join(', '):''}. Preview placement is illustrative; check physical fit before buying.`;scene.select(active);el('scene-status').dataset.loadMs=result.loadMs;el('scene-retry-assets').hidden=!result.failed.length;el('scene-stage').classList.toggle('is-empty',!result.rendered);el('scene-stage').dataset.emptyMessage=result.failed.length?'Models could not download. Retry below; your parts are saved.':entries.length?'No model can be placed for these selections. Check coverage or choose a marked 3D part.':'Choose components to see your build here.';}
 function shell(){const visual=el('pc-visual');if(!visual||el('scene-stage'))return;visual.innerHTML=`<div class="scene-intro"><p>Explore any selected part in 3D. Category silhouettes are illustrative; check exact dimensions before buying.</p><button class="button primary" id="scene-open" type="button">Open 3D preview</button></div><div id="scene-stage" class="scene-stage" hidden></div><div class="scene-controls" id="scene-controls" hidden><div class="scene-views" role="group" aria-label="Camera view"><button type="button" data-camera="angled">Angled</button><button type="button" data-camera="side">Side</button><button type="button" data-camera="front">Front</button><button type="button" data-camera="angled">Reset</button></div><div class="scene-views" role="group" aria-label="Camera controls"><button type="button" data-rotate="-1" aria-label="Rotate left">Rotate left</button><button type="button" data-rotate="1" aria-label="Rotate right">Rotate right</button><button type="button" data-zoom="0.85" aria-label="Zoom in">+</button><button type="button" data-zoom="1.15" aria-label="Zoom out">−</button></div><button type="button" id="scene-retry-assets" hidden>Retry model downloads</button><div class="scene-toggles"><label><input type="checkbox" id="scene-explode"> Exploded view</label><label><input type="checkbox" id="scene-panel"> Show side panel</label><label><input type="checkbox" id="scene-low"> Lower graphics detail</label></div><p class="scene-help">Drag to rotate. Scroll or pinch to zoom. Right-drag, two-finger drag, or arrow keys to pan.</p></div><p id="scene-status" role="status">Choose parts, then open the preview.</p><div id="scene-components" class="scene-components" role="group" aria-label="Inspect a component"></div><div id="scene-inspector" class="scene-inspector" aria-live="polite"></div><details class="scene-notes"><summary>Accuracy and model coverage</summary><p>Models are simplified, with approximate mounting positions. Category silhouettes use assumed sizes. Only selected fans are drawn. No cooler, radiator, or cables are added. The preview cannot guarantee clearance or thermal performance.</p><a href="/builder/model-coverage/">View component coverage and sources</a></details>`;
 el('scene-stage').addEventListener('scene-failed',()=>{scene?.dispose();scene=null;el('scene-stage').hidden=true;el('scene-controls').hidden=true;visual.querySelector('.scene-intro').hidden=false;el('scene-open').disabled=false;el('scene-open').textContent='Retry 3D preview';el('scene-status').textContent='The graphics connection was lost. Your parts list is preserved.'});
 el('scene-open').onclick=async()=>{if(loading)return;loading=true;el('scene-open').disabled=true;el('scene-open').textContent='Loading preview…';try{el('scene-status').textContent='Loading selected component models…';await catalogModels();entries.forEach(e=>e.record=library.items.find(r=>r.id===e.id));el('scene-stage').hidden=false;const mod=await import('/build-scene.js?v=20260923b');scene=mod.createBuildScene(el('scene-stage'),inspect);el('scene-controls').hidden=false;visual.querySelector('.scene-intro').hidden=true;scene.explode(el('scene-explode').checked);scene.sidePanel(el('scene-panel').checked);scene.quality(el('scene-low').checked);refreshList();await refreshScene()}catch(e){console.error("3D preview:",e);scene?.dispose();scene=null;el('scene-stage').hidden=true;el('scene-controls').hidden=true;visual.querySelector('.scene-intro').hidden=false;el('scene-status').textContent='3D preview could not start. Your parts list and compatibility checks still work. You can retry below.';el('scene-open').disabled=false;el('scene-open').textContent='Retry 3D preview'}finally{loading=false}};
 visual.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>scene?.view(b.dataset.camera));visual.querySelectorAll('[data-rotate]').forEach(b=>b.onclick=()=>scene?.rotate(Number(b.dataset.rotate)));visual.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>scene?.zoom(Number(b.dataset.zoom)));el('scene-retry-assets').onclick=()=>refreshScene();el('scene-explode').onchange=e=>scene?.explode(e.target.checked);el('scene-panel').onchange=e=>scene?.sidePanel(e.target.checked);el('scene-low').onchange=e=>scene?.quality(e.target.checked);
 }
 renderPCVisual=function(analysis){shell();entries=buildSlotDefs.flatMap(slot=>buildInstances(slot.id).map((item,index)=>{const placement=partPlacement(slot.id,index,item.part,analysis);return{id:item.part.id,name:item.part.name,slot:slot.id,index,placement:slot.id==='fan'?fanPlacement(index,item.part):null,modules:item.part.specs.Modules||1,unplaced:placement.fit?'':placement.reason,record:library?.items.find(r=>r.id===item.part.id)}}));el('pc-visual-count').textContent=entries.length+' '+(entries.length===1?'part':'parts')+' selected';el('pc-visual-status').textContent='Check physical clearances with the exact component manuals before buying.';refreshList();refreshScene();pendingVisualAction=null;};
 document.addEventListener('click',e=>{const row=e.target.closest('.builder-row');if(row)inspect(row.dataset.builderRow)});document.addEventListener('focusin',e=>{const row=e.target.closest('.builder-row');if(row)inspect(row.dataset.builderRow)});window.addEventListener('pagehide',()=>{scene?.dispose();scene=null;loading=false;if(el('scene-stage')){el('scene-stage').hidden=true;el('scene-controls').hidden=true;document.querySelector('.scene-intro').hidden=false;el('scene-open').disabled=false;el('scene-open').textContent='Open 3D preview';el('scene-status').textContent='Reopen the preview to explore your saved parts.'}});renderPCVisual(analyzeBuild());
})();
